using System;using System.Diagnostics;using System.Net;using System.Net.Sockets;using System.Reflection;using System.IO;
public static class OrphanPortHarness {
 public static int Main(string[] args){if(args.Length>0){if(args[0]=="listen"){var owned=new TcpListener(IPAddress.Loopback,Int32.Parse(args[1]));owned.ExclusiveAddressUse=true;owned.Start();Console.WriteLine("ready");Console.ReadLine();owned.Stop();return 0;}return Int32.Parse(args[0]);}
  var listener=new TcpListener(IPAddress.Loopback,0);listener.ExclusiveAddressUse=true;listener.Start();
  try{int port=((IPEndPoint)listener.LocalEndpoint).Port;foreach(int exit in new[]{0,2,32,48})using(var child=Process.Start(new ProcessStartInfo(Process.GetCurrentProcess().MainModule.FileName,exit.ToString()){UseShellExecute=false,CreateNoWindow=true})){if(!child.WaitForExit(5000))throw new Exception("synthetic child timeout");try{VisionDBrowserLauncher.Setup.ReadyOnPort(child,port);throw new Exception("unexpected ready");}catch(VisionDBrowserLauncher.Setup.StartupFailure e){if(e.ExitCode!=exit||!e.Occupied||VisionDBrowserLauncher.Setup.CanKeepDegraded(true,false,e)!=(exit==48)||VisionDBrowserLauncher.Setup.CanKeepDegraded(false,false,e)||VisionDBrowserLauncher.Setup.CanKeepDegraded(true,true,e))throw new Exception("degraded ownership/diagnostic boundary");}}
   if(VisionDBrowserLauncher.LocalHelper.PortAvailable(port))throw new Exception("foreign listener was disturbed");
  }finally{listener.Stop();}
  int fresh=VisionDBrowserLauncher.LocalHelper.FreshPort();using(var service=Process.Start(new ProcessStartInfo(Process.GetCurrentProcess().MainModule.FileName,"listen "+fresh){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardInput=true})){try{if(service.StandardOutput.ReadLine()!="ready")throw new Exception("fixture not listening");VisionDBrowserLauncher.Setup.ReadyOnPort(service,fresh);bool wrong=false;try{VisionDBrowserLauncher.Setup.ReadyOnPort(service,fresh==65535?fresh-1:fresh+1);}catch(InvalidOperationException){wrong=true;}if(!wrong)throw new Exception("wrong configured port accepted");}finally{service.StandardInput.WriteLine();if(!service.WaitForExit(5000))throw new Exception("fixture stop timeout");}}
  string root=Path.Combine(Path.GetTempPath(),"visiond-repair-state-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{string active=Path.Combine(root,"active"),candidate=Path.Combine(root,"candidate");File.WriteAllText(active,"old-owned-key-fixture");File.WriteAllText(candidate,"new-owned-key-fixture");string old=VisionDBrowserLauncher.Setup.Hash(active);int staged=0;
   if(VisionDBrowserLauncher.LocalHelper.AwaitRepairConfirmation(()=>false,()=>staged++,()=>{},2)||VisionDBrowserLauncher.Setup.Hash(active)!=old||!File.Exists(candidate))throw new Exception("unconfirmed changed old config");
   if(!VisionDBrowserLauncher.LocalHelper.AwaitRepairConfirmation(()=>true,()=>{throw new Exception("confirmed candidate restaged");},()=>{},2))throw new Exception("crash resume");
   bool changed=false;try{VisionDBrowserLauncher.LocalHelper.PromoteRepair(active,candidate,"wrong-hash");}catch(InvalidDataException){changed=true;}if(!changed||!File.Exists(candidate))throw new Exception("concurrent config overwritten");
   VisionDBrowserLauncher.LocalHelper.PromoteRepair(active,candidate,old);if(File.ReadAllText(active)!="new-owned-key-fixture"||File.Exists(candidate))throw new Exception("atomic same-candidate promotion");
