   if(File.Exists(candidate)||File.ReadAllText(active).Contains("old-owned"))throw new Exception("revoked key restored");
  }finally{foreach(string p in Directory.GetFiles(root))File.Delete(p);Directory.Delete(root);}
  Console.WriteLine("PASS isolated actual early-exit/occupied-port degraded ownership, foreign listener preserved, fresh-port PID readiness, no-confirm/crash-resume/config-CAS/promotion");return 0;
 }
